import{_ as o,o as a,c as l,ae as i}from"./chunks/framework.RRduUuAx.js";const b=JSON.parse('{"title":"iCost 내역 가져오기","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/guide/08-icost-bill-import-guide.md","filePath":"v1/ko/guide/08-icost-bill-import-guide.md"}'),e={name:"v1/ko/guide/08-icost-bill-import-guide.md"};function r(d,t,s,n,c,h){return a(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="icost-내역-가져오기" tabindex="-1">iCost 내역 가져오기 <a class="header-anchor" href="#icost-내역-가져오기" aria-label="Permalink to &quot;iCost 내역 가져오기&quot;">​</a></h1><h2 id="📋-개요" tabindex="-1">📋 개요 <a class="header-anchor" href="#📋-개요" aria-label="Permalink to &quot;📋 개요&quot;">​</a></h2><p>이 가이드는 <strong>iCost</strong>에서 내보낸 내역을 <strong>Koala</strong>로 가져오는 방법을 안내합니다.</p><p>Koala는 현재 <strong>iCost Excel 내보내기 파일</strong>(<code>.xlsx</code> / <code>.xls</code>)을 지원하며, <strong>iCost CSV 파일은 지원하지 않습니다</strong>.</p><hr><h2 id="📱-1단계-icost에서-내역-내보내기" tabindex="-1">📱 1단계: iCost에서 내역 내보내기 <a class="header-anchor" href="#📱-1단계-icost에서-내역-내보내기" aria-label="Permalink to &quot;📱 1단계: iCost에서 내역 내보내기&quot;">​</a></h2><p>iCost는 버전에 따라 메뉴명이 조금 다를 수 있지만 흐름은 같습니다. “내보내기/데이터 내보내기”에서 Excel 형식으로 저장하세요.</p><h3 id="단계-1-내보내기-메뉴-찾기" tabindex="-1">단계 1: 내보내기 메뉴 찾기 <a class="header-anchor" href="#단계-1-내보내기-메뉴-찾기" aria-label="Permalink to &quot;단계 1: 내보내기 메뉴 찾기&quot;">​</a></h3><ol><li>iCost 앱을 엽니다</li><li><strong>설정 / 더보기</strong>(또는 “我的”의 설정)로 이동합니다</li><li><strong>导出 / 数据导出 / 导出账单</strong>(표기 다를 수 있음)을 찾습니다</li></ol><h3 id="단계-2-excel로-내보내기" tabindex="-1">단계 2: Excel로 내보내기 <a class="header-anchor" href="#단계-2-excel로-내보내기" aria-label="Permalink to &quot;단계 2: Excel로 내보내기&quot;">​</a></h3><ol><li>내보내기 형식: <strong>Excel(.xlsx / .xls)</strong> 선택</li><li>기간 선택(권장: 한 번에 3개월 이내)</li><li>내보내기 후 기기에 저장(공유 → 파일에 저장 등)</li></ol><blockquote><p>⚠️ 중요: CSV로 내보내면 Koala에서 “CSV는 지원하지 않습니다. Excel을 사용해 주세요”라고 안내됩니다.</p></blockquote><hr><h2 id="📱-2단계-koala로-가져오기" tabindex="-1">📱 2단계: Koala로 가져오기 <a class="header-anchor" href="#📱-2단계-koala로-가져오기" aria-label="Permalink to &quot;📱 2단계: Koala로 가져오기&quot;">​</a></h2><h3 id="단계-1-가져오기-화면-열기" tabindex="-1">단계 1: 가져오기 화면 열기 <a class="header-anchor" href="#단계-1-가져오기-화면-열기" aria-label="Permalink to &quot;단계 1: 가져오기 화면 열기&quot;">​</a></h3><ol><li>Koala 앱을 엽니다</li><li>하단의 <strong>설정</strong>을 탭합니다</li><li><strong>내역 가져오기</strong>를 찾아 들어갑니다</li></ol><h3 id="단계-2-가져오기-소스-선택" tabindex="-1">단계 2: 가져오기 소스 선택 <a class="header-anchor" href="#단계-2-가져오기-소스-선택" aria-label="Permalink to &quot;단계 2: 가져오기 소스 선택&quot;">​</a></h3><ol><li><strong>가져오기 소스</strong>를 탭합니다</li><li><strong>iCost</strong>를 선택합니다</li></ol><blockquote><p>⚠️ 중요: 반드시 iCost를 선택해야 합니다. 다른 소스로 파싱하면 헤더를 찾지 못하거나 열이 어긋날 수 있습니다.</p></blockquote><h3 id="단계-3-파일-선택" tabindex="-1">단계 3: 파일 선택 <a class="header-anchor" href="#단계-3-파일-선택" aria-label="Permalink to &quot;단계 3: 파일 선택&quot;">​</a></h3><ol><li><strong>파일 경로</strong>를 탭합니다</li><li>iCost에서 내보낸 Excel(<code>.xlsx</code> / <code>.xls</code>)을 선택합니다</li><li>파일명이 표시되는지 확인합니다</li></ol><h3 id="단계-4-장부-연결" tabindex="-1">단계 4: 장부 연결 <a class="header-anchor" href="#단계-4-장부-연결" aria-label="Permalink to &quot;단계 4: 장부 연결&quot;">​</a></h3><ol><li><strong>장부 연결</strong>을 탭합니다</li><li>가져올 장부를 선택합니다</li></ol><h3 id="단계-5-파싱-및-미리보기" tabindex="-1">단계 5: 파싱 및 미리보기 <a class="header-anchor" href="#단계-5-파싱-및-미리보기" aria-label="Permalink to &quot;단계 5: 파싱 및 미리보기&quot;">​</a></h3><ol><li>우측 상단의 <strong>파싱</strong>을 탭합니다</li><li>파싱 성공 시 미리보기 화면으로 이동합니다</li><li>미리보기에서 카테고리/계정/시간/금액/태그/메모 등을 수정한 뒤 가져올 수 있습니다</li></ol><h3 id="단계-6-가져오기-실행" tabindex="-1">단계 6: 가져오기 실행 <a class="header-anchor" href="#단계-6-가져오기-실행" aria-label="Permalink to &quot;단계 6: 가져오기 실행&quot;">​</a></h3><ol><li>확인이 끝나면 <strong>가져오기</strong>를 탭합니다</li><li>완료될 때까지 기다립니다</li></ol><hr><h2 id="📋-icost-excel-형식-참고" tabindex="-1">📋 iCost Excel 형식(참고) <a class="header-anchor" href="#📋-icost-excel-형식-참고" aria-label="Permalink to &quot;📋 iCost Excel 형식(참고)&quot;">​</a></h2><p>Koala의 검증 기준:</p><ul><li>읽을 수 있는 워크시트가 있어야 합니다</li><li>헤더 행에 **“日期”**가 포함되어 있어야 합니다(헤더 행을 찾는 기준)</li></ul><blockquote><p>📝 팁: iCost 내보내기에서 언어를 선택할 수 있다면 중국어 헤더로 내보내는 것을 권장합니다(최소한 “日期”를 포함).</p></blockquote><h3 id="읽는-열-열-위치-기준" tabindex="-1">읽는 열(열 위치 기준) <a class="header-anchor" href="#읽는-열-열-위치-기준" aria-label="Permalink to &quot;읽는 열(열 위치 기준)&quot;">​</a></h3><p>Koala는 iCost Excel의 일부 열을 “열 위치”로 읽고, 나머지는 무시합니다.</p><table tabindex="0"><thead><tr><th>열</th><th>필드</th><th>설명</th></tr></thead><tbody><tr><td>1</td><td>날짜</td><td><code>yyyy-MM-dd</code> / <code>yyyy/MM/dd</code> / <code>yyyy-MM-ddTHH:mm:ss</code> / <code>yyyy-MM-dd HH:mm:ss</code>, Excel 시리얼 날짜 지원</td></tr><tr><td>2</td><td>유형</td><td>“支出”(지출) 또는 “收入”(수입) 키워드를 포함해야 합니다</td></tr><tr><td>3</td><td>금액</td><td><code>+</code>/<code>-</code> 허용, 가져오기 시 부호 제거 및 천 단위 구분자 <code>,</code> 처리</td></tr><tr><td>4</td><td>상위 분류</td><td>Koala 상위 카테고리명 매칭</td></tr><tr><td>5</td><td>하위 분류</td><td>비어 있으면 상위 분류 값을 사용</td></tr><tr><td>6</td><td>계정</td><td>비어 있으면 기본 계정으로 대체</td></tr><tr><td>8</td><td>메모</td><td>메모 텍스트</td></tr><tr><td>9</td><td>통화 코드</td><td><code>CNY</code> / <code>USD</code> 등, 비어 있거나 매칭 실패 시 장부 통화 사용</td></tr><tr><td>10</td><td>태그</td><td>여러 태그는 쉼표로 구분(<code>,</code>), 중국어 쉼표 <code>，</code>도 지원</td></tr></tbody></table><h3 id="koala로의-매핑-개요" tabindex="-1">Koala로의 매핑(개요) <a class="header-anchor" href="#koala로의-매핑-개요" aria-label="Permalink to &quot;Koala로의 매핑(개요)&quot;">​</a></h3><ul><li>날짜(row[0]) → 날짜</li><li>유형(row[1]) → 수입/지출</li><li>금액(row[2]) → 금액</li><li>상위 분류(row[3]) → 상위 카테고리(매칭/생성)</li><li>하위 분류(row[4], 비어 있으면 상위 사용) → 하위 카테고리(매칭/생성)</li><li>계정(row[5], 비어 있으면 기본 계정) → 계정</li><li>7번째 열(row[6]) → 사용하지 않음</li><li>메모(row[7]) → 메모</li><li>통화 코드(row[8]) → 통화(코드로 매칭, 실패 시 장부 통화로 대체)</li><li>태그(row[9]) → 태그(파싱/생성 후 연결)</li></ul><hr><h2 id="⚠️-유의사항" tabindex="-1">⚠️ 유의사항 <a class="header-anchor" href="#⚠️-유의사항" aria-label="Permalink to &quot;⚠️ 유의사항&quot;">​</a></h2><ol><li><strong>Excel만 지원</strong>: iCost CSV 파일은 가져올 수 없습니다.</li><li><strong>자동 중복 제거 없음</strong>: 같은 파일을 두 번 가져오면 중복 내역이 생성됩니다. 동일 기간을 반복해서 가져오지 않도록 주의하세요.</li><li><strong>헤더 언어</strong>: 헤더 행에 “日期”가 있어야 합니다. 영어 헤더로 내보내면 헤더를 찾지 못해 실패할 수 있습니다.</li><li><strong>계정이 비어 있는 경우</strong>: “계정” 열이 비어 있으면 기본 계정으로 들어갑니다. 미리보기에서 계정을 일괄 수정하거나, iCost에서 계정을 채운 뒤 다시 내보내세요.</li><li><strong>카테고리 매칭</strong>: “상위+하위” 이름으로 매칭합니다. 매칭 실패 시 미리보기에서 수정 후 가져오세요.</li></ol><hr><h2 id="🔧-자주-묻는-질문" tabindex="-1">🔧 자주 묻는 질문 <a class="header-anchor" href="#🔧-자주-묻는-질문" aria-label="Permalink to &quot;🔧 자주 묻는 질문&quot;">​</a></h2><h3 id="q1-icost-헤더를-찾지-못했습니다" tabindex="-1">Q1: “iCost 헤더를 찾지 못했습니다”. <a class="header-anchor" href="#q1-icost-헤더를-찾지-못했습니다" aria-label="Permalink to &quot;Q1: “iCost 헤더를 찾지 못했습니다”.&quot;">​</a></h3><p>흔한 원인:</p><ol><li>헤더 행에 “日期”가 없음(예: 영어 헤더로 내보냄)</li><li>iCost 내보내기 파일이 아니거나, 편집으로 구조가 깨짐</li><li>Excel이 비어 있거나 워크시트가 없음</li></ol><p>iCost에서 다시 내보내고, 중국어 헤더를 우선 선택해 주세요.</p><h3 id="q2-계정이-비어-있어서-모두-같은-계정으로-들어갔어요" tabindex="-1">Q2: 계정이 비어 있어서 모두 같은 계정으로 들어갔어요. <a class="header-anchor" href="#q2-계정이-비어-있어서-모두-같은-계정으로-들어갔어요" aria-label="Permalink to &quot;Q2: 계정이 비어 있어서 모두 같은 계정으로 들어갔어요.&quot;">​</a></h3><p>“계정” 열이 비어 있을 때의 기본 동작입니다. 미리보기에서 계정을 일괄 수정하거나, iCost에서 계정을 채운 뒤 다시 가져오세요.</p><h3 id="q3-카테고리가-매칭되지-않습니다" tabindex="-1">Q3: 카테고리가 매칭되지 않습니다. <a class="header-anchor" href="#q3-카테고리가-매칭되지-않습니다" aria-label="Permalink to &quot;Q3: 카테고리가 매칭되지 않습니다.&quot;">​</a></h3><p>미리보기에서 단건으로 올바른 카테고리를 선택해 주세요. 또는 Koala에 iCost 내보내기와 같은 이름의 카테고리를 먼저 만든 뒤 다시 파싱하세요.</p><hr><p><strong>마지막 업데이트</strong>: 2026년 4월</p>',52)])])}const q=o(e,[["render",r]]);export{b as __pageData,q as default};
